sqlGroup.select:
select a.*, b1.dname as display_showname, (select count(1) as level from sys_menu aa where find_in_set(aa.id,getMenuParLst(a.id))) as `level` from sys_menu a LEFT JOIN sys_dict b1 ON a.display = b1.dval and b1.tcode = 'MENU_DISPLAY'
and a.pid = #{pid}
order by a.seq desc

select * from ( select distinct concat('m_',m.id) as id, m.`mname` name, concat('m_',m.pid) pId, '1' flag, m.seq from sys_menu m left join sys_rela_role_auth b on m.id = b.authId and b.authType = '1' left join sys_role c on b.roleId = c.id where m.display = #{display}
and c.roleKey = #{roleKey}
union all select distinct concat('f_',a.id) as id, a.name, concat('m_',a.menuid) as pId, '2' as flag, a.seq from sys_func a left join sys_rela_role_auth b on a.id=b.authId and b.authType='2' left join sys_role c on b.roleId = c.id left join sys_menu m on m.id=a.menuid where a.actionType='2' and a.display=#{display} and m.display = #{display}
and c.roleKey = #{roleKey}
) mf order by mf.pId desc,mf.seq desc

select a.*, b.mname as pname from sys_menu a left join sys_menu b on a.pid = b.id
and a.id = #{id}
and a.pid = #{pid}
